// String functions of the Mini stdlib (stdlib/kotlin/text/Strings.kt), compiled from source.
fun show(label: String, value: String) {
    println(label + " = [" + value + "]")
}

fun main() {
    val s = "Hello, World"
    show("substring", s.substring(7))
    show("substring2", s.substring(0, 5))
    show("take", s.take(3))
    show("takeLast", s.takeLast(5))
    show("drop", s.drop(7))
    show("dropLast", s.dropLast(7))
    println(s.startsWith("Hello"))
    println(s.startsWith("World"))
    println(s.startsWith("World", 7))
    println(s.endsWith("World"))
    println(s.endsWith('d'))
    println(s.indexOf('o'))
    println(s.indexOf('o', 5))
    println(s.indexOf("World"))
    println(s.indexOf("xyz"))
    println(s.lastIndexOf('o'))
    println(s.lastIndexOf("o"))
    println(s.contains("lo, W"))
    println(s.contains('z'))
    show("lowercase", s.lowercase())
    show("uppercase", s.uppercase())
    show("trim", "  \t padded \n ".trim())
    show("trimStart", "  x ".trimStart())
    show("trimEnd", "  x ".trimEnd())
    show("padStart", "7".padStart(3, '0'))
    show("padEnd", "ab".padEnd(5, '.'))
    show("padStart-noop", "abcdef".padStart(3))
    show("repeat", "ab".repeat(3))
    show("repeat0", "ab".repeat(0))
    show("reversed", s.reversed())
    show("replace-char", s.replace('l', 'L'))
    show("replace-str", s.replace("World", "Mini"))
    show("replace-none", s.replace("zzz", "y"))
    show("replace-empty", "ab".replace("", "-"))
    show("substringBefore", "key=value=x".substringBefore("="))
    show("substringAfter", "key=value=x".substringAfter("="))
    show("substringBeforeLast", "key=value=x".substringBeforeLast("="))
    show("substringAfterLast", "key=value=x".substringAfterLast("="))
    show("substringBefore-missing", "abc".substringBefore("#"))
    show("removePrefix", "prefix-body".removePrefix("prefix-"))
    show("removeSuffix", "body.kt".removeSuffix(".kt"))
    println("".isEmpty())
    println("a".isNotEmpty())
    println("  \t".isBlank())
    println(" a ".isBlank())
    println(s.first())
    println(s.last())
    println(s.length)
    var vowels = 0
    for (i in 0 until s.length) {
        val c = s[i].lowercaseChar()
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') vowels++
    }
    println(vowels)
    println("apple" < "banana")
    println("b".compareTo("a"))
}
